const copy: Record<Locale, AccountCopy> = { en, vi };
type Mutation = (data: FinanceData) => FinanceData;
type Commit = (mutation: Mutation, success?: () => void) => Promise<boolean>;
type Currency = SubscriptionCurrency;
type View = { kind: 'list' } | { kind: 'detail'; id: string } | { kind: 'account'; id?: string } | { kind: 'rates' } | { kind: 'setup' } | { kind: 'transfer'; id?: string; from?: string; to?: string; statementId?: string } | { kind: 'reconcile'; id: string } | { kind: 'statement'; accountId: string; id?: string } | { kind: 'deleteAccount'; id: string } | { kind: 'deleteStatement'; id: string; accountId: string };

function useAccountCopy() { const { locale } = useI18n(); return copy[locale]; }
export function formatAccountMoney(amount: number, currency: Currency, locale: Locale) {
  return formatMoney(amount, currency, locale === 'vi' ? 'vi-VN' : 'en-US');
}
function Field({ label, hint, children }: { label: string; hint?: string; children: ReactNode }) { return <label className="field"><span>{label}</span>{children}{hint && <small className="field-help">{hint}</small>}</label>; }
function Note({ children, warning = false }: { children: ReactNode; warning?: boolean }) { return <p className={`account-note${warning ? ' is-warning' : ''}`}>{children}</p>; }
function FormProblem({ message }: { message: string }) { const ref = useRef<HTMLDivElement>(null); useEffect(() => { ref.current?.scrollIntoView({ block: 'nearest' }); ref.current?.focus({ preventScroll: true }); }, [message]); return <div className="account-form-error" role="alert" tabIndex={-1} ref={ref}>{message}</div>; }
function Actions({ busy, onCancel, label }: { busy: boolean; onCancel: () => void; label?: string }) { const c = useAccountCopy(); return <div className="sheet-actions"><button type="button" className="cancel-action" onClick={onCancel} disabled={busy}>{c.cancel}</button><button className="primary-action" type="submit" disabled={busy}>{busy ? c.saving : label ?? c.save}</button></div>; }
function AmountInput({ value, onChange, currency, signed = false, disabled = false }: { value: string; onChange: (value: string) => void; currency: Currency; signed?: boolean; disabled?: boolean }) { return <div className="money-input"><input inputMode={signed ? 'text' : 'decimal'} value={value} onChange={(e) => onChange(e.target.value)} disabled={disabled} placeholder="0" autoComplete="off" /><strong>{currency}</strong></div>; }
function getTitle(account: Account, c: AccountCopy) {
  if (account.kind === 'legacy') return c.legacy;
  if ((account.id === 'account-cash' || account.id === 'demo-account-cash') && account.name === 'Tiền mặt') return c.cash;
  if (account.id === 'demo-account-bank' && account.name === 'Tài khoản ngân hàng') return c.bank;
  if (account.id === 'demo-account-card' && account.name === 'Thẻ tín dụng') return c.credit_card;
  return account.name;
}
export function accountDisplayName(account: Account, locale: Locale) { return getTitle(account, copy[locale]); }

function reorderGroup(data: FinanceData, ids: string[]) {
  const group = new Set(ids); let index = 0;
  return reorderAccounts(data, data.accounts.filter((account) => !account.archived && account.kind !== 'legacy').map((account) => group.has(account.id) ? ids[index++] : account.id));
}

export function AccountsOverview({ data, onOpen, onChange }: { data: FinanceData; onOpen: (accountId?: string) => void; onChange: (updater: Mutation) => Promise<unknown> }) {
  const { locale } = useI18n(); const c = copy[locale];
  const balances = deriveAccountBalances(data).filter(({ account, balance }) => (!account.archived || balance !== 0) && (account.kind !== 'legacy' || balance !== 0 || !data.setupComplete));
  return <section className="accounts-overview surface-raised" aria-labelledby="accounts-overview-title">
    <div className="section-heading"><h2 id="accounts-overview-title">{c.title}</h2><button className="quiet-link" type="button" onClick={() => onOpen()}>{c.manage}<ArrowsLeftRight size={16} weight="bold" aria-hidden="true" /></button></div>
    {!data.setupComplete && <button className="accounts-setup-entry" type="button" onClick={() => onOpen()}><span><strong>{c.setup}</strong><small>{c.setupHelp}</small></span><Plus size={20} aria-hidden="true" /></button>}
    {balances.length === 0 && <div className="account-empty"><Wallet size={28} aria-hidden="true" /><strong>{c.noAccounts}</strong><p>{c.noAccountsHelp}</p><button type="button" className="quiet-link" onClick={() => onOpen()}><Plus size={17} />{c.add}</button></div>}
    {(['assets', 'cards'] as const).map((group) => {
      const rows = balances.filter(({ account }) => (account.kind === 'credit_card') === (group === 'cards'));
      return rows.length > 0 && <div className="account-overview-group" key={group}><h3>{c[group]}</h3><SortableAccountRows onReorder={(ids) => onChange((current) => reorderGroup(current, ids))} rows={rows.map(({ account, balance, reportingBalance }) => ({ id: account.id, label: getTitle(account, c), movable: !account.archived && account.kind !== 'legacy', content: <button type="button" className="account-source-row" onClick={() => onOpen(account.id)}>
        <span className={`account-source-icon${account.kind === 'credit_card' ? ' is-card' : ''}`}><AccountIcon account={account} size={30} /></span><span className="account-source-copy"><strong>{getTitle(account, c)}</strong><small>{account.kind === 'credit_card' ? (balance < 0 ? c.debt : c.credit) : c[account.kind]}</small>{getDefaultAccountId(data) === account.id && <small className="account-default-label">{locale === 'vi' ? 'Mặc định' : 'Default'}</small>}</span><span className="account-source-value"><strong>{formatAccountMoney(account.kind === 'credit_card' ? Math.abs(balance) : balance, account.currency, locale)}</strong>{account.currency !== 'VND' && <small className={reportingBalance === null ? 'account-missing-rate' : ''}>{reportingBalance === null ? c.unconverted : `≈ ${formatAccountMoney(account.kind === 'credit_card' ? Math.abs(reportingBalance) : reportingBalance, 'VND', locale)}`}</small>}</span>
      </button> }))} /></div>;
    })}
  </section>;
}

export function AccountsSheet({ data, onChange, onClose, initialAccountId, initialTransactionId, initialTransfer, onAddTransaction, onEditTransaction }: {
  data: FinanceData; onChange: (updater: Mutation) => Promise<unknown>; onClose: () => void; initialAccountId?: string; initialTransactionId?: string; initialTransfer?: boolean; onAddTransaction?: (accountId: string) => void; onEditTransaction?: (transaction: Transaction) => void;
}) {
  const { locale } = useI18n(); const c = copy[locale]; const labelId = useId();
  const [view, setView] = useState<View>(initialTransactionId || initialTransfer ? { kind: 'transfer', id: initialTransactionId } : initialAccountId ? { kind: 'detail', id: initialAccountId } : { kind: 'list' });
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const dialogRef = useRef<HTMLElement>(null); const closeRef = useRef(onClose); const busyRef = useRef(busy);
  useEffect(() => { closeRef.current = onClose; busyRef.current = busy; }, [onClose, busy]);
  useEffect(() => {
    const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const alreadyLocked = document.body.classList.contains('is-sheet-open'); document.body.classList.add('is-sheet-open'); dialogRef.current?.focus();
    const keydown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { e.preventDefault(); e.stopImmediatePropagation(); if (!busyRef.current) closeRef.current(); }
      if (e.key !== 'Tab') return;
      const items = Array.from(dialogRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), summary, a[href], [tabindex="0"]') ?? []).filter((item) => item.offsetParent !== null);
      const first = items[0]; const last = items.at(-1);
      if (!first || !last) { e.preventDefault(); return; }
      if (e.shiftKey && (document.activeElement === first || document.activeElement === dialogRef.current)) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
    };
    window.addEventListener('keydown', keydown, true);
    return () => { if (!alreadyLocked) document.body.classList.remove('is-sheet-open'); window.removeEventListener('keydown', keydown, true); previous?.focus(); };
  }, []);
  const go = (next: View) => { if (busyRef.current) return; setError(''); setNotice(''); setView(next); requestAnimationFrame(() => { dialogRef.current?.scrollTo({ top: 0 }); dialogRef.current?.focus(); }); };
  const commit: Commit = async (mutation, success) => {
    if (busyRef.current) return false;
    busyRef.current = true; setBusy(true); setError(''); setNotice('');
    try { await onChange(mutation); success?.(); setNotice(c.saved); return true; }
    catch (cause) { setError(financeError(cause, locale)); return false; }
    finally { busyRef.current = false; setBusy(false); }
  };
  const accountId = 'accountId' in view ? view.accountId : 'id' in view && view.kind !== 'transfer' ? view.id : undefined;
  const account = data.accounts.find((item) => item.id === accountId);
  const back = () => go(account && view.kind !== 'detail' && view.kind !== 'account' ? { kind: 'detail', id: account.id } : { kind: 'list' });
  const title = view.kind === 'list' ? c.title : view.kind === 'detail' ? account ? getTitle(account, c) : c.title : view.kind === 'account' ? view.id ? c.edit : c.add : view.kind === 'rates' ? c.rates : view.kind === 'setup' ? c.setup : view.kind === 'transfer' ? view.to && data.accounts.find((item) => item.id === view.to)?.kind === 'credit_card' ? c.repay : c.transfer : view.kind === 'reconcile' ? c.reconcile : view.kind === 'statement' ? view.id ? c.editStatement : c.addStatement : view.kind === 'deleteAccount' ? c.deleteAccountTitle : c.statementDelete;
  return <div className="sheet-backdrop accounts-backdrop" onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) onClose(); }}>
    <section className="form-sheet accounts-sheet" role="dialog" aria-modal="true" aria-labelledby={labelId} tabIndex={-1} ref={dialogRef} aria-busy={busy}>
      <header className="sheet-header"><div>{view.kind !== 'list' && <button type="button" className="account-back" onClick={back} disabled={busy}><ArrowLeft size={16} weight="bold" aria-hidden="true" />{c.back}</button>}<h2 id={labelId}>{title}</h2>{view.kind === 'list' && <p>{c.subtitle}</p>}</div><button type="button" onClick={onClose} aria-label={c.close} disabled={busy}><X size={21} weight="bold" aria-hidden="true" /></button></header>
      {error && <FormProblem message={error} />}{notice && <p className="account-save-notice" role="status"><Check size={16} aria-hidden="true" />{notice}</p>}
      <fieldset className="account-content-fieldset" disabled={busy}>
        {view.kind === 'list' && <AccountsList data={data} go={go} commit={commit} />}
        {view.kind === 'detail' && account && <AccountDetail data={data} account={account} go={go} commit={commit} onAddTransaction={onAddTransaction} onEditTransaction={onEditTransaction} />}
        {view.kind === 'account' && <AccountForm key={view.id ?? 'new'} initial={data.accounts.find((item) => item.id === view.id)} commit={commit} busy={busy} onCancel={back} onSaved={(id) => setView({ kind: 'detail', id })} />}
        {view.kind === 'rates' && <RatesPanel data={data} commit={commit} busy={busy} />}
        {view.kind === 'setup' && <SetupForm data={data} commit={commit} busy={busy} onCancel={back} onSaved={() => setView({ kind: 'list' })} />}
        {view.kind === 'transfer' && <TransferForm key={`${view.id ?? 'new'}-${view.statementId ?? ''}`} data={data} initial={data.transactions.find((item) => item.id === view.id)} fromId={view.from} toId={view.to} statementId={view.statementId} commit={commit} busy={busy} onCancel={back} onSaved={() => setView({ kind: 'list' })} />}
        {view.kind === 'reconcile' && account && <ReconcileForm data={data} account={account} commit={commit} busy={busy} onCancel={back} onSaved={() => setView({ kind: 'detail', id: account.id })} />}
        {view.kind === 'statement' && account && <StatementForm account={account} initial={data.statements.find((item) => item.id === view.id)} commit={commit} busy={busy} onCancel={back} onSaved={() => setView({ kind: 'detail', id: account.id })} />}
        {view.kind === 'deleteAccount' && account && <form onSubmit={(e) => { e.preventDefault(); void commit((current) => deleteAccount(current, account.id), () => setView({ kind: 'list' })); }}><Note>{c.deleteAccountHelp}</Note><Actions busy={busy} onCancel={back} label={c.deleteConfirm} /></form>}
        {view.kind === 'deleteStatement' && <form onSubmit={(e) => { e.preventDefault(); void commit((current) => deleteStatement(current, view.id), () => setView({ kind: 'detail', id: view.accountId })); }}><Note>{c.statementDeleteHelp}</Note><Actions busy={busy} onCancel={back} label={c.deleteStatement} /></form>}
      </fieldset>
    </section>
  </div>;
}

function AccountsList({ data, go, commit }: { data: FinanceData; go: (view: View) => void; commit: Commit }) {
  const { locale } = useI18n(); const c = copy[locale]; const balances = deriveAccountBalances(data);
  return <div>
    <div className="account-toolbar"><button type="button" className="primary-action" onClick={() => go(data.setupComplete ? { kind: 'account' } : { kind: 'setup' })}><Plus size={18} aria-hidden="true" />{c.add}</button><button type="button" className="cancel-action" onClick={() => go({ kind: 'transfer' })}><ArrowsLeftRight size={18} aria-hidden="true" />{c.transfer}</button><button type="button" className="cancel-action" onClick={() => go({ kind: 'rates' })}>{c.rates}</button></div>
    {!data.setupComplete && <button type="button" className="accounts-setup-entry" onClick={() => go({ kind: 'setup' })}><span><strong>{c.setup}</strong><small>{c.setupHelp}</small></span><Plus size={20} aria-hidden="true" /></button>}
    {(['assets', 'cards', 'legacy', 'archivedGroup'] as const).map((group) => {
      const rows = balances.filter(({ account }) => group === 'archivedGroup' ? account.archived : !account.archived && (group === 'legacy' ? account.kind === 'legacy' : group === 'cards' ? account.kind === 'credit_card' : account.kind !== 'legacy' && account.kind !== 'credit_card'));
      return rows.length > 0 && <section className="account-list-section" key={group}><h3 className="account-section-title">{c[group]}</h3><SortableAccountRows onReorder={(ids) => commit((current) => reorderGroup(current, ids))} rows={rows.map(({ account, balance, reportingBalance }) => ({ id: account.id, label: getTitle(account, c), movable: !account.archived && account.kind !== 'legacy', content: <button type="button" className="account-source-row" onClick={() => go({ kind: 'detail', id: account.id })}><span className={`account-source-icon${account.kind === 'credit_card' ? ' is-card' : ''}`}><AccountIcon account={account} size={30} /></span><span className="account-source-copy"><strong>{getTitle(account, c)}</strong><small>{account.currency} · {account.kind === 'credit_card' ? balance < 0 ? c.debt : c.credit : c[account.kind]}</small>{getDefaultAccountId(data) === account.id && <small className="account-default-label">{locale === 'vi' ? 'Mặc định' : 'Default'}</small>}</span><span className="account-source-value"><strong>{formatAccountMoney(account.kind === 'credit_card' ? Math.abs(balance) : balance, account.currency, locale)}</strong>{account.currency !== 'VND' && <small className={reportingBalance === null ? 'account-missing-rate' : ''}>{reportingBalance === null ? c.unconverted : `≈ ${formatAccountMoney(account.kind === 'credit_card' ? Math.abs(reportingBalance) : reportingBalance, 'VND', locale)}`}</small>}</span></button> }))} /></section>;
    })}
  </div>;
}

function AccountDetail({ data, account, go, commit, onAddTransaction, onEditTransaction }: { data: FinanceData; account: Account; go: (view: View) => void; commit: Commit; onAddTransaction?: (accountId: string) => void; onEditTransaction?: (transaction: Transaction) => void }) {
  const { locale, formatDate, c: shared } = useI18n(); const c = copy[locale]; const b = deriveAccountBalances(data).find((item) => item.account.id === account.id)!;
  const report = deriveAccountReport(data, account.id); const money = (amount: number) => formatAccountMoney(amount, account.currency, locale);
  const statements = data.statements.filter((item) => item.accountId === account.id).sort((a, b) => b.closingDate.localeCompare(a.closingDate));
  const subscriptions = data.subscriptions.filter((item) => item.accountId === account.id);
  const quote = latestExchangeRate(data, account.currency);
  const unused = account.openingBalance === 0 && !data.transactions.some((item) => item.accountId === account.id || item.toAccountId === account.id) && !subscriptions.length && !statements.length;
  const kindLabels = { income: c.income, expense: c.expense, refund: c.refund, transfer: c.transfer, adjustment: c.adjustment };
  return <div className="account-detail">
    <div className="account-detail-balance"><span className={`account-source-icon${account.kind === 'credit_card' ? ' is-card' : ''}`}><AccountIcon account={account} size={38} /></span><div><span>{account.kind === 'credit_card' ? b.balance < 0 ? c.debt : c.credit : c.balance}</span><strong>{money(account.kind === 'credit_card' ? Math.abs(b.balance) : b.balance)}</strong>{account.currency !== 'VND' && <small>{b.reportingBalance === null ? c.unconverted : `${c.estimated} ≈ ${formatAccountMoney(account.kind === 'credit_card' ? Math.abs(b.reportingBalance) : b.reportingBalance, 'VND', locale)}${quote ? ` · ${c.rateDate} ${formatDate(quote.date)}` : ''}`}</small>}</div></div>
    {!account.archived && account.kind !== 'legacy' && <button type="button" className="account-default-action" disabled={getDefaultAccountId(data) === account.id} onClick={() => void commit((current) => setDefaultAccount(current, account.id))}><Check size={18} aria-hidden="true" />{getDefaultAccountId(data) === account.id ? locale === 'vi' ? 'Nguồn tiền mặc định' : 'Default account' : locale === 'vi' ? 'Đặt làm nguồn mặc định' : 'Set as default account'}</button>}
    {account.kind === 'legacy' && <Note warning={data.setupComplete && b.balance !== 0}>{data.setupComplete && b.balance !== 0 ? c.setupResidual : c.historicalHelp}</Note>}
    {account.archived && <Note>{c.archivedHelp}{b.balance !== 0 ? ` ${c.archivedNonzero}` : ''}</Note>}
    {account.kind !== 'credit_card' && account.kind !== 'legacy' && b.balance < 0 && <Note warning>{c.balanceWarning}</Note>}
    {b.availableCredit !== undefined && <div><p className="account-muted">{c.availableLimit}</p><strong>{money(b.availableCredit)}</strong>{b.availableCredit < 0 && <Note warning>{c.limitWarning}</Note>}</div>}
    <div className="account-toolbar">{account.archived ? <><button type="button" className="primary-action" onClick={() => void commit((current) => unarchiveAccount(current, account.id))}>{c.restore}</button>{account.kind === 'legacy' && b.balance !== 0 && <button type="button" className="cancel-action" onClick={() => go({ kind: 'reconcile', id: account.id })}>{c.reconcile}</button>}</> : <>
      {account.kind !== 'legacy' && onAddTransaction && <button type="button" className="primary-action" onClick={() => onAddTransaction(account.id)}><Plus size={18} aria-hidden="true" />{c.addTransaction}</button>}
      {account.kind !== 'legacy' && <button type="button" className="cancel-action" onClick={() => go(account.kind === 'credit_card' ? { kind: 'transfer', to: account.id } : { kind: 'transfer', from: account.id })}><ArrowsLeftRight size={18} aria-hidden="true" />{account.kind === 'credit_card' ? c.repay : c.transfer}</button>}
      <button type="button" className="cancel-action" onClick={() => go({ kind: 'reconcile', id: account.id })}>{c.reconcile}</button>
    </>}</div>
    <section><h3 className="account-section-title">{c.allTime} · {account.currency}</h3><dl className="account-metrics"><div><dt>{c.opening}</dt><dd>{money(report.openingBalance)}</dd></div>{report.openingInPeriod !== 0 && <div><dt>{locale === 'vi' ? 'Số dư nguồn mở trong kỳ' : 'Account opened during period'}</dt><dd>{money(report.openingInPeriod)}</dd></div>}{([['income', report.income], ['expense', report.expense], ['transferIn', report.transferIn], ['transferOut', report.transferOut], ['adjustments', report.adjustments]] as const).map(([label, amount]) => <div key={label}><dt>{c[label]}</dt><dd>{money(amount)}</dd></div>)}<div><dt>{locale === 'vi' ? 'Số dư cuối kỳ' : 'Closing balance'}</dt><dd>{money(report.closingBalance)}</dd></div></dl></section>
    {account.kind === 'credit_card' && <section><div className="account-inline-heading"><h3>{c.statements}</h3>{!account.archived && <button type="button" className="quiet-link" onClick={() => go({ kind: 'statement', accountId: account.id })}><Plus size={16} aria-hidden="true" />{c.addStatement}</button>}</div>
      {statements.length === 0 && <p className="account-muted">{c.statementHelp}</p>}
      {statements.map((statement) => { const status = deriveStatementStatus(data, statement.id); return <article className="account-statement" key={statement.id}><div className="account-statement-top"><strong>{c.statement} · {formatDate(statement.closingDate)}</strong><span className={`account-status${status.remaining === 0 ? ' is-paid' : status.isOverdue ? ' is-overdue' : ''}`}>{status.remaining === 0 ? c.settled : `${status.isOverdue ? c.overdue : c.due} ${formatDate(statement.dueDate)}`}</span></div><dl className="account-metrics"><div><dt>{c.statementAmount}</dt><dd>{money(statement.amount)}</dd></div><div><dt>{c.remaining}</dt><dd>{money(status.remaining)}</dd></div><div><dt>{c.paid}</dt><dd>{money(status.paid)}</dd></div>{statement.minimumPayment !== undefined && <div><dt>{c.minimumRemaining}</dt><dd>{money(status.minimumRemaining)}</dd></div>}</dl><div className="account-toolbar">{!account.archived && status.remaining > 0 && <button type="button" className="primary-action" onClick={() => go({ kind: 'transfer', to: account.id, statementId: statement.id })}>{c.repay}</button>}<button type="button" className="cancel-action" disabled={account.archived} onClick={() => go({ kind: 'statement', accountId: account.id, id: statement.id })}><PencilSimple size={16} aria-hidden="true" />{c.editStatement}</button><button type="button" className="account-icon-button account-danger" aria-label={c.deleteStatement} onClick={() => go({ kind: 'deleteStatement', id: statement.id, accountId: account.id })}><Trash size={18} aria-hidden="true" /></button></div></article>; })}
    </section>}
    <section><div className="account-inline-heading"><h3>{c.activity}</h3><span className="account-muted">{report.transactions.length}</span></div>{report.transactions.length === 0 ? <p className="account-muted">{c.noActivity}</p> : <ul className="account-activity">{report.transactions.map((item) => {
      const amount = item.kind === 'transfer' && item.toAccountId === account.id ? item.receivedAmount! : item.amount;
      const other = item.kind === 'transfer' ? data.accounts.find((other) => other.id === (item.accountId === account.id ? item.toAccountId : item.accountId)) : undefined;
      const title = item.systemTitle === 'setup' ? c.setup : item.systemTitle === 'transfer_fee' ? `${c.fee.split(' (')[0]} · ${item.title}` : item.titleKey ? shared.demo.transactions[item.titleKey] : item.title || kindLabels[item.kind];
      const groupedTransfer = item.groupId ? data.transactions.find((entry) => entry.kind === 'transfer' && entry.groupId === item.groupId) : undefined;
      const editable = !!groupedTransfer || item.kind === 'transfer' || (item.kind !== 'adjustment' && !!onEditTransaction);
      const content = <><span><strong>{title}</strong><small>{formatDate(item.date)} · {kindLabels[item.kind]}{other ? ` · ${getTitle(other, c)}` : ''}</small></span><span className={`account-activity-value${amount > 0 ? ' is-positive' : amount < 0 ? ' is-negative' : ''}`}><strong>{amount > 0 ? '+' : ''}{money(amount)}</strong></span></>;
      return <li key={item.id}>{editable ? <button className="account-activity-row" type="button" aria-label={`${c.transactionEdit}: ${title}`} onClick={() => groupedTransfer ? go({ kind: 'transfer', id: groupedTransfer.id }) : item.kind === 'transfer' ? go({ kind: 'transfer', id: item.id }) : onEditTransaction?.(item)}>{content}</button> : <div className="account-activity-row">{content}</div>}</li>;
    })}</ul>}</section>
    <section><h3 className="account-section-title">{c.subscriptions}</h3>{subscriptions.length ? <ul className="account-activity">{subscriptions.map((item) => <li key={item.id}><div className="account-activity-row"><span><strong>{item.name}</strong><small>{formatDate(item.nextRenewal)} · {shared.subscriptions.status[item.status]}</small></span><span className="account-activity-value"><strong>{new Intl.NumberFormat(locale === 'vi' ? 'vi-VN' : 'en-US', { style: 'currency', currency: item.currency }).format(item.amount)}</strong></span></div></li>)}</ul> : <p className="account-muted">{c.noSubscriptions}</p>}</section>
    {account.kind !== 'legacy' && <details className="account-more"><summary>{c.more}</summary><div className="account-toolbar"><button type="button" className="cancel-action" onClick={() => go({ kind: 'account', id: account.id })}><PencilSimple size={17} aria-hidden="true" />{c.edit}</button>{!account.archived && <button type="button" className="cancel-action" onClick={() => void commit((current) => archiveAccount(current, account.id))}><Archive size={17} aria-hidden="true" />{c.archive}</button>}{unused && <button type="button" className="cancel-action account-danger" onClick={() => go({ kind: 'deleteAccount', id: account.id })}><Trash size={17} aria-hidden="true" />{c.remove}</button>}</div><p className="account-muted">{c.cannotArchive}</p></details>}
  </div>;
}

function AccountForm({ initial, commit, busy, onCancel, onSaved }: { initial?: Account; commit: Commit; busy: boolean; onCancel: () => void; onSaved: (id: string) => void }) {
  const c = useAccountCopy(); const { locale } = useI18n(); const vi = locale === 'vi'; const today = localTodayIso();
  const [id] = useState(() => initial?.id ?? createId('account')); const [name, setName] = useState(initial?.name ?? '');
  const [kind, setKind] = useState<Account['kind']>(initial?.kind ?? 'bank'); const [currency, setCurrency] = useState<Currency>(initial?.currency ?? 'VND');
  const [bankId, setBankId] = useState(initial?.bankId ?? '');
  const [bankCountry, setBankCountry] = useState<BankCountry>(() => (getBank(initial?.bankId ?? '') ?? inferBank(initial?.name ?? ''))?.country ?? (initial?.currency === 'USD' ? 'US' : initial?.currency === 'GBP' ? 'GB' : 'VN'));
  const bankAccount = kind === 'bank' || kind === 'credit_card';
  const previewBank = bankId ? getBank(bankId) : inferBank(name);
  const [balance, setBalance] = useState(formatMoneyAmount(initial?.kind === 'credit_card' ? Math.abs(initial.openingBalance) : initial?.openingBalance ?? 0, currency));
  const [owing, setOwing] = useState((initial?.openingBalance ?? 0) <= 0); const [date, setDate] = useState(initial?.openingDate ?? today);
  const [limit, setLimit] = useState(initial?.creditLimit !== undefined ? formatMoneyAmount(initial.creditLimit, currency) : ''); const [error, setError] = useState('');
  const submit = (event: FormEvent) => {
    event.preventDefault(); const amount = parseMoneyInput(balance, currency); const creditLimit = limit.trim() ? parseMoneyInput(limit, currency) : undefined;
    if (!name.trim() || name.trim().length > 60) { setError(c.invalidName); return; }
    if (amount === null || (kind === 'credit_card' && amount < 0) || creditLimit === null || (creditLimit !== undefined && creditLimit < 0)) { setError(c.invalidMoney); return; }
    if (!isValidDateOnly(date) || date > today) { setError(c.invalidDate); return; }
    setError(''); const openingBalance = kind === 'credit_card' && owing ? -amount : amount;
    void commit((current) => saveAccount(current, { id, name: name.trim(), kind, currency, bankId: bankAccount && bankId ? bankId : undefined, openingBalance: initial?.openingBalance ?? openingBalance, openingDate: initial?.openingDate ?? date, ...(kind === 'credit_card' && creditLimit !== undefined ? { creditLimit } : {}) }, initial?.id), () => onSaved(id));
  };
  return <form className="account-form" onSubmit={submit} noValidate>{error && <FormProblem message={error} />}
    <Field label={c.name}><input autoFocus maxLength={60} value={name} onChange={(e) => setName(e.target.value)} placeholder={c.namePlaceholder} /></Field>
    <div className="account-form-grid"><Field label={c.kind}><select value={kind} onChange={(e) => setKind(e.target.value as Account['kind'])} disabled={!!initial}>{(['cash', 'bank', 'ewallet', 'credit_card'] as const).map((value) => <option key={value} value={value}>{c[value]}</option>)}</select></Field><Field label={c.currency}><select value={currency} onChange={(e) => setCurrency(e.target.value as Currency)} disabled={!!initial}>{CURRENCIES.map((value) => <option key={value}>{value}</option>)}</select></Field></div>
    {bankAccount && <div className="account-bank-fields">
      <div className="account-form-grid"><Field label={vi ? 'Quốc gia ngân hàng' : 'Bank country'}><select aria-label={vi ? 'Quốc gia ngân hàng' : 'Bank country'} value={bankCountry} onChange={(event) => { setBankCountry(event.target.value as BankCountry); setBankId(''); }}><option value="VN">{vi ? 'Việt Nam' : 'Vietnam'}</option><option value="US">{vi ? 'Mỹ' : 'United States'}</option><option value="GB">{vi ? 'Anh' : 'United Kingdom'}</option></select></Field>
      <Field label={vi ? 'Icon ứng dụng ngân hàng' : 'Bank app icon'}><select aria-label={vi ? 'Icon ứng dụng ngân hàng' : 'Bank app icon'} value={bankId} onChange={(event) => { const selected = getBank(event.target.value); setBankId(event.target.value); if (selected && (!name.trim() || name === previewBank?.name)) setName(selected.name); }}><option value="">{vi ? 'Tự nhận diện theo tên' : 'Detect from account name'}</option><option value="generic">{vi ? 'Biểu tượng ngân hàng chung' : 'Generic bank icon'}</option>{BANKS.filter((bank) => bank.country === bankCountry).map((bank) => <option value={bank.id} key={bank.id}>{bank.name}</option>)}</select></Field></div>
      <div className="account-bank-preview"><AccountIcon account={{ kind, name, bankId: bankId || undefined }} size={38} /><span>{previewBank?.name ?? (vi ? 'Biểu tượng ngân hàng chung' : 'Generic bank icon')}<small>{vi ? 'Biểu tượng không thay đổi tiền tệ của nguồn.' : 'The icon does not change the account currency.'}</small></span></div>
    </div>}
    {initial ? <Note>{c.currencyLocked} {c.adjustmentHelp}</Note> : <>
      {kind === 'credit_card' && <fieldset className="account-content-fieldset"><legend className="account-section-title">{c.cardBalance}</legend><div className="account-selection"><label><input type="radio" name="card-position" checked={owing} onChange={() => setOwing(true)} />{c.owing}</label><label><input type="radio" name="card-position" checked={!owing} onChange={() => setOwing(false)} />{c.overpaid}</label></div></fieldset>}
      <div className="account-form-grid"><Field label={kind === 'credit_card' ? owing ? c.debt : c.credit : c.opening}><AmountInput value={balance} onChange={setBalance} currency={currency} signed={kind !== 'credit_card'} /></Field><Field label={c.openingDate}><input type="date" value={date} max={today} onChange={(e) => setDate(e.target.value)} /></Field></div><Note>{c.openingHelp}</Note>
    </>}
    {kind === 'credit_card' && <Field label={c.limit} hint={c.limitHelp}><AmountInput value={limit} onChange={setLimit} currency={currency} /></Field>}
    <Actions busy={busy} onCancel={onCancel} />
  </form>;
}

function ReconcileForm({ data, account, commit, busy, onCancel, onSaved }: { data: FinanceData; account: Account; commit: Commit; busy: boolean; onCancel: () => void; onSaved: () => void }) {
  const { locale } = useI18n(); const c = copy[locale]; const today = localTodayIso(); const currentBalance = deriveAccountBalances(data).find((item) => item.account.id === account.id)!.balance;
  const [value, setValue] = useState(formatMoneyAmount(currentBalance, account.currency)); const [reason, setReason] = useState(''); const [error, setError] = useState('');
  const amount = parseMoneyInput(value, account.currency); const difference = amount === null ? null : amount - currentBalance;
  const submit = (e: FormEvent) => { e.preventDefault(); if (amount === null) { setError(c.invalidMoney); return; } if (!reason.trim()) { setError(c.emptyReason); return; } if (difference === 0) { setError(c.unchanged); return; } setError(''); void commit((current) => reconcileAccount(current, account.id, amount, today, reason.trim()), onSaved); };
  return <form className="account-form" onSubmit={submit} noValidate>{error && <FormProblem message={error} />}<Note>{c.reconcileHelp}</Note><Field label={c.actualBalance} hint={`${c.date}: ${today}`}><AmountInput value={value} onChange={setValue} currency={account.currency} signed /></Field><dl className="account-comparison"><div><dt>{c.recordedBalance}</dt><dd>{formatAccountMoney(currentBalance, account.currency, locale)}</dd></div><div><dt>{c.adjustment}</dt><dd>{difference === null || !Number.isSafeInteger(difference) ? '—' : formatAccountMoney(difference, account.currency, locale)}</dd></div></dl><Field label={c.reason}><input value={reason} maxLength={160} onChange={(e) => setReason(e.target.value)} placeholder={c.reasonPlaceholder} /></Field><Note>{c.adjustmentHelp}</Note><Actions busy={busy} onCancel={onCancel} /></form>;
}

function TransferForm({ data, initial, fromId, toId, statementId, commit, busy, onCancel, onSaved }: { data: FinanceData; initial?: Transaction; fromId?: string; toId?: string; statementId?: string; commit: Commit; busy: boolean; onCancel: () => void; onSaved: () => void }) {
  const { locale, formatDate } = useI18n(); const c = copy[locale]; const today = localTodayIso();
  const choices = data.accounts.filter((account) => account.kind !== 'legacy' && (!account.archived || account.id === initial?.accountId || account.id === initial?.toAccountId));
  const initialFrom = initial?.accountId ?? fromId ?? choices.find((account) => account.id !== toId && account.kind !== 'credit_card')?.id ?? choices.find((account) => account.id !== toId)?.id ?? '';
  const initialTo = initial?.toAccountId ?? toId ?? choices.find((account) => account.id !== initialFrom)?.id ?? '';
  const [from, setFrom] = useState(initialFrom); const [to, setTo] = useState(initialTo);
  const source = choices.find((account) => account.id === from); const destination = choices.find((account) => account.id === to);
  const selectedStatement = statementId ? data.statements.find((item) => item.id === statementId) : undefined;
  const remaining = selectedStatement ? deriveStatementStatus(data, selectedStatement.id).remaining : undefined;
  const initialFee = initial?.groupId ? data.transactions.find((item) => item.kind === 'expense' && item.groupId === initial.groupId) : undefined;
  const [amount, setAmount] = useState(initial && source ? formatMoneyAmount(Math.abs(initial.amount), source.currency) : remaining !== undefined && source?.currency === destination?.currency ? formatMoneyAmount(remaining, source!.currency) : '');
  const [received, setReceived] = useState(initial?.receivedAmount !== undefined && destination ? formatMoneyAmount(initial.receivedAmount, destination.currency) : remaining !== undefined && destination ? formatMoneyAmount(remaining, destination.currency) : '');
  const [fee, setFee] = useState(initialFee && source ? formatMoneyAmount(Math.abs(initialFee.amount), source.currency) : '');
  const [feeReporting, setFeeReporting] = useState(initialFee?.reportingAmount !== undefined ? String(Math.abs(initialFee.reportingAmount)) : '');
  const [date, setDate] = useState(initial?.date ?? today); const [title, setTitle] = useState(initial?.title ?? ''); const [statement, setStatement] = useState(initial?.statementId ?? statementId ?? '');
  const [error, setError] = useState(''); const [deleting, setDeleting] = useState(false);
  if (choices.length < 2) return <div className="account-empty"><ArrowsLeftRight size={28} aria-hidden="true" /><p>{c.transferNeedsAccounts}</p><button type="button" className="cancel-action" onClick={onCancel}>{c.back}</button></div>;
  const sentMinor = source ? parseMoneyInput(amount, source.currency) : null;
  const sameCurrency = source?.currency === destination?.currency;
  const receivedMinor = sameCurrency ? sentMinor : destination ? parseMoneyInput(received, destination.currency) : null;
  const fromBalance = deriveAccountBalances(data).find((item) => item.account.id === from)?.balance;
  const minimumDate = [source?.openingDate, destination?.openingDate].filter((value): value is string => !!value).sort().at(-1);
  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (!source || !destination || source.id === destination.id) { setError(c.sameAccount); return; }
    if (sentMinor === null || receivedMinor === null || sentMinor <= 0 || receivedMinor <= 0) { setError(c.positiveMoney); return; }
    const feeMinor = fee.trim() ? parseMoneyInput(fee, source.currency) : undefined; const reporting = feeReporting.trim() ? parseMoneyInput(feeReporting, 'VND') : undefined;
    if (feeMinor === null || reporting === null || (feeMinor !== undefined && feeMinor < 0) || (reporting !== undefined && reporting < 0)) { setError(c.nonnegativeMoney); return; }
    if (!isValidDateOnly(date) || date > today || (!!minimumDate && date < minimumDate)) { setError(`${c.invalidDate}${minimumDate ? ` ${c.openingDate}: ${minimumDate}.` : ''}`); return; }
    setError(''); void commit((current) => saveTransfer(current, { accountId: source.id, toAccountId: destination.id, amount: sentMinor, receivedAmount: receivedMinor, date, title: title.trim(), fee: feeMinor, feeReportingAmount: reporting, statementId: statement || undefined }, initial?.id), onSaved);
  };
  if (deleting && initial) return <form className="account-form" onSubmit={(e) => { e.preventDefault(); void commit((current) => deleteLedgerTransaction(current, initial.id), onSaved); }}><Note warning>{c.removeTransferHelp}</Note><Actions busy={busy} onCancel={() => setDeleting(false)} label={c.removeTransfer} /></form>;
  return <form className="account-form" onSubmit={submit} noValidate>{error && <FormProblem message={error} />}<Note>{c.transferNote}</Note>
    <div className="account-form-grid"><Field label={c.from}><select value={from} onChange={(e) => { setFrom(e.target.value); setAmount(''); setFee(''); setFeeReporting(''); }}>{choices.map((account) => <option value={account.id} key={account.id}>{getTitle(account, c)} · {account.currency}{account.archived ? ` · ${c.archived}` : ''}</option>)}</select></Field><Field label={c.to}><select value={to} onChange={(e) => { setTo(e.target.value); setReceived(''); setStatement(''); }}>{choices.map((account) => <option value={account.id} key={account.id}>{getTitle(account, c)} · {account.currency}{account.archived ? ` · ${c.archived}` : ''}</option>)}</select></Field></div>
    {source && <Field label={c.sent} hint={fromBalance === undefined ? undefined : `${c.balance}: ${formatAccountMoney(fromBalance, source.currency, locale)}`}><AmountInput value={amount} onChange={setAmount} currency={source.currency} /></Field>}
    {!sameCurrency && destination && <Field label={c.received}><AmountInput value={received} onChange={setReceived} currency={destination.currency} /></Field>}
    {!sameCurrency && source && destination && sentMinor !== null && sentMinor > 0 && receivedMinor !== null && receivedMinor > 0 && <p className="account-muted">{c.exchange}: 1 {source.currency} = {new Intl.NumberFormat(locale === 'vi' ? 'vi-VN' : 'en-US', { maximumFractionDigits: 8 }).format(toMajorUnits(receivedMinor, destination.currency) / toMajorUnits(sentMinor, source.currency))} {destination.currency}</p>}
    <div className="account-form-grid"><Field label={c.date}><input type="date" value={date} min={minimumDate} max={today} onChange={(e) => { setDate(e.target.value); setFeeReporting(''); }} /></Field>{source && <Field label={c.fee}><AmountInput value={fee} onChange={(value) => { setFee(value); setFeeReporting(''); }} currency={source.currency} /></Field>}</div><p className="account-muted">{c.feeHelp}</p>
    {source && source.currency !== 'VND' && fee.trim() && <Field label={c.feeReporting} hint={c.feeReportingHelp}><AmountInput value={feeReporting} onChange={setFeeReporting} currency="VND" /></Field>}
    {destination?.kind === 'credit_card' && <Field label={c.statementSelect}><select value={statement} onChange={(e) => setStatement(e.target.value)}><option value="">{c.noStatement}</option>{data.statements.filter((item) => item.accountId === destination.id).sort((a, b) => b.closingDate.localeCompare(a.closingDate)).map((item) => <option value={item.id} key={item.id}>{formatDate(item.closingDate)} · {c.remaining} {formatAccountMoney(deriveStatementStatus(data, item.id).remaining, destination.currency, locale)}</option>)}</select></Field>}
    <Field label={c.titleLabel}><input value={title} maxLength={160} onChange={(e) => setTitle(e.target.value)} /></Field><Actions busy={busy} onCancel={onCancel} />
    {initial && <button type="button" className="quiet-link account-danger" onClick={() => setDeleting(true)}>{c.removeTransfer}</button>}
  </form>;
}

function StatementForm({ account, initial, commit, busy, onCancel, onSaved }: { account: Account; initial?: CardStatement; commit: Commit; busy: boolean; onCancel: () => void; onSaved: () => void }) {
  const c = useAccountCopy(); const today = localTodayIso(); const [closingDate, setClosingDate] = useState(initial?.closingDate ?? today); const [dueDate, setDueDate] = useState(initial?.dueDate ?? '');
  const [amount, setAmount] = useState(initial ? formatMoneyAmount(initial.amount, account.currency) : ''); const [minimum, setMinimum] = useState(initial?.minimumPayment !== undefined ? formatMoneyAmount(initial.minimumPayment, account.currency) : ''); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); const parsed = parseMoneyInput(amount, account.currency); const min = minimum.trim() ? parseMoneyInput(minimum, account.currency) : undefined;
    if (parsed === null || parsed < 0 || min === null || (min !== undefined && min < 0)) { setError(c.nonnegativeMoney); return; }
    if (!isValidDateOnly(closingDate) || closingDate > today || !isValidDateOnly(dueDate) || dueDate < closingDate || (min !== undefined && min > parsed)) { setError(c.statementInvalid); return; }
    setError(''); void commit((current) => saveStatement(current, { id: initial?.id, accountId: account.id, closingDate, dueDate, amount: parsed, minimumPayment: min }), onSaved);
  };
  return <form className="account-form" onSubmit={submit} noValidate>{error && <FormProblem message={error} />}<Note>{c.statementHelp}</Note><div className="account-form-grid"><Field label={c.closingDate}><input type="date" max={today} value={closingDate} onChange={(e) => setClosingDate(e.target.value)} /></Field><Field label={c.dueDate}><input type="date" min={closingDate} value={dueDate} onChange={(e) => setDueDate(e.target.value)} /></Field></div><Field label={c.statementAmount}><AmountInput value={amount} onChange={setAmount} currency={account.currency} /></Field><Field label={c.minimum}><AmountInput value={minimum} onChange={setMinimum} currency={account.currency} /></Field><Actions busy={busy} onCancel={onCancel} /></form>;
}

function RatesPanel({ data, commit, busy, currencies }: { data: FinanceData; commit: Commit; busy: boolean; currencies?: Currency[] }) {
  const c = useAccountCopy(); const [extras, setExtras] = useState<Currency[]>([]); const [selected, setSelected] = useState<Currency>('USD');
  const visible = [...new Set([...(currencies ?? data.accounts.filter((account) => !account.archived).map((account) => account.currency)), ...extras])].filter((currency) => currency !== 'VND');
  return <div className="account-rate-list"><Note>{c.ratesHelp}</Note>{visible.length === 0 && <p className="account-muted">{c.noForeign}</p>}
    {visible.map((currency) => <RateForm key={currency} data={data} currency={currency} commit={commit} busy={busy} />)}
    {!currencies && <div className="account-form-grid"><Field label={c.currency}><select value={selected} onChange={(e) => setSelected(e.target.value as Currency)}>{CURRENCIES.filter((currency) => currency !== 'VND').map((currency) => <option key={currency}>{currency}</option>)}</select></Field><button type="button" className="cancel-action" onClick={() => setExtras((current) => [...new Set([...current, selected])])} disabled={visible.some((currency) => currency === selected)}><Plus size={17} aria-hidden="true" />{c.rates}</button></div>}
  </div>;
}

function RateForm({ data, currency, commit, busy }: { data: FinanceData; currency: Currency; commit: Commit; busy: boolean }) {
  const { locale } = useI18n(); const c = copy[locale]; const today = localTodayIso(); const existing = latestExchangeRate(data, currency);
  const [rate, setRate] = useState(existing?.rate ?? ''); const [date, setDate] = useState(existing?.date ?? today); const [source, setSource] = useState(existing?.source ?? ''); const [error, setError] = useState(''); const [saved, setSaved] = useState(false);
  const submit = (e: FormEvent) => { e.preventDefault(); if (!/^\d+(\.\d+)?$/.test(rate.trim()) || !Number.isFinite(Number(rate)) || Number(rate) <= 0) { setError(c.missingRate); return; } if (!isValidDateOnly(date) || date > today) { setError(c.invalidDate); return; } setError(''); setSaved(false); void commit((current) => setExchangeRate(current, { currency, rate: rate.trim(), date, source: source.trim() || (locale === 'vi' ? 'Nhập thủ công' : 'Manual entry') }), () => setSaved(true)); };
  return <form className="account-rate-form" onSubmit={submit} noValidate><h3>{currency} → VND</h3>{error && <FormProblem message={error} />}<div className="account-form-grid"><Field label={`${c.perUnit} ${currency}`}><input inputMode="decimal" value={rate} onChange={(e) => { setRate(e.target.value); setSaved(false); }} placeholder="0" /></Field><Field label={c.dateRate}><input type="date" max={today} value={date} onChange={(e) => { setDate(e.target.value); setSaved(false); }} /></Field></div><Field label={c.source}><input value={source} maxLength={120} onChange={(e) => { setSource(e.target.value); setSaved(false); }} placeholder={c.sourcePlaceholder} /></Field><button type="submit" className="primary-action" disabled={busy}>{busy ? c.saving : c.save}</button>{saved && <p className="account-save-notice" role="status"><Check size={16} aria-hidden="true" />{c.rateSaved}</p>}</form>;
}

type SetupDraft = { id: string; name: string; kind: Exclude<Account['kind'], 'legacy'>; currency: Currency; balance: string; owing: boolean; limit: string };
function freshSetupDraft(): SetupDraft { return { id: createId('account'), name: '', kind: 'bank', currency: 'VND', balance: '0', owing: true, limit: '' }; }
function SetupForm({ data, commit, busy, onCancel, onSaved }: { data: FinanceData; commit: Commit; busy: boolean; onCancel: () => void; onSaved: () => void }) {
  const { locale } = useI18n(); const c = copy[locale]; const today = localTodayIso();
  const [rows, setRows] = useState<SetupDraft[]>(() => [freshSetupDraft()]); const [date, setDate] = useState(today); const [error, setError] = useState('');
  const update = (id: string, patch: Partial<SetupDraft>) => setRows((current) => current.map((row) => row.id === id ? { ...row, ...patch } : row));
  const inputs: AccountInput[] = []; let valid = rows.length > 0 && isValidDateOnly(date) && date <= today;
  for (const row of rows) { const amount = parseMoneyInput(row.balance, row.currency); const limit = row.limit.trim() ? parseMoneyInput(row.limit, row.currency) : undefined;
    if (!row.name.trim() || row.name.trim().length > 60 || amount === null || (row.kind === 'credit_card' && amount < 0) || limit === null || (limit !== undefined && limit < 0)) { valid = false; continue; }
    inputs.push({ id: row.id, name: row.name.trim(), kind: row.kind, currency: row.currency, openingBalance: row.kind === 'credit_card' && row.owing ? -amount : amount, openingDate: date, ...(row.kind === 'credit_card' && limit !== undefined ? { creditLimit: limit } : {}) });
  }
  let preview: ReturnType<typeof previewAccountSetup> | null = null;
  if (valid) { try { preview = previewAccountSetup(data, inputs, date); } catch { preview = null; } }
  const currencies = [...new Set([...rows.map((row) => row.currency), ...data.accounts.map((account) => account.currency)])].filter((currency) => currency !== 'VND');
  const submit = (e: FormEvent) => { e.preventDefault(); if (!valid) { setError(c.setupMissingName); return; } if (!preview || preview.difference === null) { setError(c.setupRates); return; } setError(''); void commit((current) => setupAccounts(current, inputs, date), onSaved); };
  return <div className="account-form">{error && <FormProblem message={error} />}<Note>{c.setupIntro}</Note><Field label={c.balanceAsOf}><input type="date" value={date} max={today} onChange={(e) => setDate(e.target.value)} /></Field>
    <div>{rows.map((row, index) => <fieldset key={row.id} className="account-setup-row"><div className="account-inline-heading"><h3><AccountIcon account={row} size={24} />{row.name.trim() || `${c.title} ${index + 1}`}</h3><button className="account-icon-button account-danger" type="button" aria-label={`${c.removeRow} ${index + 1}`} onClick={() => setRows((current) => current.filter((item) => item.id !== row.id))} disabled={rows.length === 1}><Trash size={18} aria-hidden="true" /></button></div>
      <Field label={c.name}><input value={row.name} maxLength={60} onChange={(e) => update(row.id, { name: e.target.value })} placeholder={c.namePlaceholder} /></Field><div className="account-form-grid"><Field label={c.kind}><select value={row.kind} onChange={(e) => update(row.id, { kind: e.target.value as SetupDraft['kind'] })}>{(['cash', 'bank', 'ewallet', 'credit_card'] as const).map((kind) => <option key={kind} value={kind}>{c[kind]}</option>)}</select></Field><Field label={c.currency}><select value={row.currency} onChange={(e) => update(row.id, { currency: e.target.value as Currency })}>{CURRENCIES.map((currency) => <option key={currency}>{currency}</option>)}</select></Field></div>
      {row.kind === 'credit_card' && <div className="account-selection"><label><input type="radio" name={`setup-position-${row.id}`} checked={row.owing} onChange={() => update(row.id, { owing: true })} />{c.owing}</label><label><input type="radio" name={`setup-position-${row.id}`} checked={!row.owing} onChange={() => update(row.id, { owing: false })} />{c.overpaid}</label></div>}
      <Field label={row.kind === 'credit_card' ? row.owing ? c.debt : c.credit : c.balance}><AmountInput value={row.balance} onChange={(balance) => update(row.id, { balance })} currency={row.currency} signed={row.kind !== 'credit_card'} /></Field>{row.kind === 'credit_card' && <Field label={c.limit} hint={c.limitHelp}><AmountInput value={row.limit} onChange={(limit) => update(row.id, { limit })} currency={row.currency} /></Field>}
    </fieldset>)}</div><button type="button" className="cancel-action" onClick={() => setRows((current) => [...current, freshSetupDraft()])}><Plus size={18} aria-hidden="true" />{c.addAnother}</button>
    {currencies.length > 0 && <section><h3 className="account-section-title">{c.setupAddRate}</h3><RatesPanel data={data} commit={commit} busy={busy} currencies={currencies} /></section>}
    <form className="account-form" onSubmit={submit} noValidate>{preview ? <><dl className="account-comparison"><div><dt>{c.oldTotal}</dt><dd>{preview.oldTotal === null ? '—' : formatAccountMoney(preview.oldTotal, 'VND', locale)}</dd></div><div><dt>{c.newTotal}</dt><dd>{preview.newTotal === null ? '—' : formatAccountMoney(preview.newTotal, 'VND', locale)}</dd></div><div><dt>{c.difference}</dt><dd>{preview.difference === null ? '—' : formatAccountMoney(preview.difference, 'VND', locale)}</dd></div></dl><Note warning={preview.difference === null}>{preview.difference === null ? `${c.setupRates} (${preview.missingCurrencies.join(', ')})` : c.differenceHelp}</Note></> : <Note>{c.setupBlocked}</Note>}{currencies.length > 0 && <p className="account-muted">{c.setupCurrencyNote}</p>}<Actions busy={busy} onCancel={onCancel} label={c.setupSave} /></form>
  </div>;
}
